/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_persons_insert` BEFORE INSERT ON `tb_people` FOR EACH ROW BEGIN
    SET NEW.given_names  = TRIM(NEW.given_names);
    SET NEW.family_names = NULLIF(TRIM(NEW.family_names), '');
    SET NEW.country_code = UPPER(TRIM(NEW.country_code));
    SET NEW.phone        = NULLIF(TRIM(NEW.phone), '');

    IF NEW.given_names = '' THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'given_names no puede estar vacío';
    END IF;

    IF NEW.birth_date IS NOT NULL AND NEW.birth_date > CURDATE() THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'birth_date no puede ser una fecha futura';
    END IF;
END */;;
