DELIMITER ;;
CREATE DEFINER=`root`@`localhost` FUNCTION `fn_generate_random_email`(p_prefix VARCHAR(20)) RETURNS varchar(100) CHARSET utf8mb4
    DETERMINISTIC
BEGIN
    DECLARE v_domain VARCHAR(50);
    DECLARE v_random_num INT;

    SET v_random_num = FLOOR(100000 + RAND() * 900000);
    SET v_domain = ELT(FLOOR(1 + RAND() * 4), 'gmail.com', 'yahoo.com', 'outlook.com', 'utxicotepec.edu.mx');

    RETURN CONCAT(p_prefix, '_', v_random_num, '@', v_domain);
END ;;
DELIMITER ;
