/*!50003 DROP PROCEDURE IF EXISTS `sp_generate_users_batch` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_generate_users_batch`(
    IN p_total_users INT,
    IN p_country VARCHAR(50),
    IN p_min_age INT,
    IN p_max_age INT,
    IN p_active_percentage DECIMAL(5,2) -- Ej: 85.00 para 85%
)
BEGIN
    DECLARE v_counter INT DEFAULT 0;
    DECLARE v_active_limit INT;
    DECLARE v_is_active TINYINT(1);
    DECLARE v_birthdate DATE;
    DECLARE v_inserted_id INT;
    DECLARE v_default_country VARCHAR(50);

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    IF p_active_percentage IS NOT NULL THEN
        SET v_active_limit = FLOOR((p_total_users * p_active_percentage) / 100);
    ELSE
        SET v_active_limit = p_total_users;
    END IF;

    START TRANSACTION;

    WHILE v_counter < p_total_users DO
        IF v_counter < v_active_limit THEN
            SET v_is_active = 1;
        ELSE
            SET v_is_active = 0;
        END IF;

        IF p_country IS NOT NULL THEN
            SET v_default_country = p_country;
        ELSE
            SET v_default_country = ELT(FLOOR(1 + RAND() * 3), 'US', 'MX', 'CA');
        END IF;

        IF p_min_age IS NOT NULL AND p_max_age IS NOT NULL THEN
            SET v_birthdate = fn_generate_birthdate_by_age(p_min_age, p_max_age);
        ELSE
            SET v_birthdate = fn_generate_birthdate_by_age(18, 65);
        END IF;

        CALL sp_insert_single_user('user_test', v_default_country, v_birthdate, v_is_active, v_inserted_id);

        -- Usuario que nace dado de baja: se registra una cancelación.
        -- Solo se inserta si existe la orden 1 (res la tenía fija).
        IF v_is_active = 0 THEN
            INSERT INTO `tb_order_cancellations` (
                `order_ID`, `seller_order_ID`, `product_offer_ID`, `requested_by`,
                `cancellation_reason`, `cancellation_status`, `requested_date`
            )
            SELECT 1, NULL, NULL, v_inserted_id,
                   'Baja de la plataforma generada automáticamente', 'Completed', NOW()
            FROM `tb_buyer_orders` WHERE `ID` = 1;
        END IF;

        SET v_counter = v_counter + 1;
    END WHILE;

    COMMIT;
END ;;
DELIMITER ;
